## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/pediatricObesityLogic.ts`

```typescript
/**
 * Pediatric Obesity Clinical Compass™
 * Logic Engine — AAP Clinical Practice Guideline 2023 (updated 2026)
 *
 * References:
 * 1. Hampl SE et al. Clinical Practice Guideline for the Evaluation and Treatment
 *    of Children and Adolescents with Obesity. Pediatrics. 2023;151(2):e2022060640.
 * 2. AAP Policy Update: Pharmacotherapy for Pediatric Obesity. Pediatrics. 2024.
 * 3. Pratt JSA et al. ASMBS Pediatric Metabolic and Bariatric Surgery Guidelines 2018
 *    (updated 2023). Surg Obes Relat Dis. 2018;14(7):882–901.
 * 4. Weghuber D et al. Once-Weekly Semaglutide in Adolescents with Obesity. NEJM. 2022.
 */

export type ObesityCategory =
  | "healthy_weight"   // BMI <85th %ile
  | "overweight"       // BMI 85–94th %ile
  | "class1_obesity"   // BMI 95–119% of 95th %ile
  | "class2_obesity"   // BMI 120–139% of 95th %ile
  | "class3_obesity";  // BMI ≥140% of 95th %ile

export interface PediatricObesityInput {
  ageYears: number;
  sex: "male" | "female";
  bmiPercentile: number;
  bmiPercentOfP95: number; // BMI as % of 95th percentile
  obesityCategory: ObesityCategory;
  durationOfObesityYears: number;
  priorTreatmentAttempts: number; // number of prior lifestyle interventions
  hasType2Diabetes: boolean;
  hasPrediabetes: boolean;
  hasHypertension: boolean;
  hasDyslipidemia: boolean;
  hasNASH: boolean; // non-alcoholic steatohepatitis / MASH
  hasOSA: boolean; // obstructive sleep apnea
  hasPCOS: boolean; // polycystic ovary syndrome (females)
  hasOrthopedicComplications: boolean; // SCFE, Blount disease
  hasIdiopathicIntracranialHypertension: boolean;
  hasDepression: boolean;
  hasBingeEatingDisorder: boolean;
  familyHistoryObesity: boolean;
  familyHistoryT2DM: boolean;
  familyMotivation: "high" | "moderate" | "low";
  priorGLP1Use: boolean;
  priorMetforminUse: boolean;
  hasContraindicationToGLP1: boolean; // MEN2, pancreatitis history, etc.
  isReadyForBariatric: boolean;
  hasBariatricContraindication: boolean;
}

export interface PediatricObesityRecommendation {
  primaryRecommendation: string;
  treatmentIntensity: string;
  lifestyleIntervention: string;
  pharmacotherapy: string;
  bariatricConsideration: string;
  comorbidityManagement: string[];
  urgentFlags: string[];
  recommendedAgents: string[];
  monitoringPlan: string;
  familyCounselingPoints: string[];
  evidenceLevel: "A" | "B" | "C";
  rationale: string;
  references: Array<{ citation: string; url: string }>;
}

export function assessPediatricObesity(
  input: PediatricObesityInput
): PediatricObesityRecommendation {
  const urgentFlags: string[] = [];
  const comorbidityMgmt: string[] = [];
  const recommendedAgents: string[] = [];
  const counselingPoints: string[] = [];

  // ─── Urgent flags ─────────────────────────────────────────────────────────
  if (input.hasIdiopathicIntracranialHypertension) {
    urgentFlags.push("URGENT: Idiopathic intracranial hypertension (IIH) — refer to neurology + ophthalmology. Rapid weight loss intervention indicated. Acetazolamide may be needed.");
  }
  if (input.hasOrthopedicComplications) {
    urgentFlags.push("URGENT: Orthopedic complication (SCFE or Blount disease) — refer to pediatric orthopedics. SCFE requires non-weight-bearing until surgical evaluation.");
  }
  if (input.hasType2Diabetes) {
    urgentFlags.push("TYPE 2 DIABETES: Initiate metformin immediately. Consider GLP-1 RA (semaglutide ≥12 years) for dual benefit on weight and glycemia. HbA1c target <7%.");
    comorbidityMgmt.push("Type 2 Diabetes: Metformin 500mg BID → titrate to 1000mg BID (max 2000mg/day). Add semaglutide (Ozempic/Wegovy) for weight + glycemic benefit. Monitor HbA1c every 3 months.");
    recommendedAgents.push("Metformin 500–2000mg/day (T2DM + obesity, ≥10 years)");
  }
  if (input.hasOSA) {
    urgentFlags.push("OBSTRUCTIVE SLEEP APNEA: Refer to sleep medicine. Polysomnography if not done. CPAP if AHI ≥5. Weight loss is the primary treatment — may resolve OSA.");
    comorbidityMgmt.push("OSA: Polysomnography + CPAP if AHI ≥5. Adenotonsillectomy if adenotonsillar hypertrophy. Weight loss is primary treatment.");
  }

  // ─── Treatment intensity (AAP 2023 4-stage model) ────────────────────────
  let treatmentIntensity: string;
  let lifestyleIntervention: string;
  let pharmacotherapy: string;
  let bariatricConsideration: string;

  if (input.obesityCategory === "healthy_weight" || input.obesityCategory === "overweight") {
    treatmentIntensity = "STAGE 1 — Prevention Plus: Counseling on healthy lifestyle behaviors. 5-2-1-0 framework (5 fruits/vegetables, ≤2 hours screen time, 1 hour activity, 0 sugary drinks). Monthly follow-up.";
    lifestyleIntervention = "5-2-1-0 healthy lifestyle counseling. Family-based behavioral counseling. Motivational interviewing. Monthly follow-up visits.";
    pharmacotherapy = "Not indicated for overweight. Pharmacotherapy reserved for obesity (BMI ≥95th %ile) with comorbidities or failed lifestyle intervention.";
    bariatricConsideration = "Not indicated for overweight category.";
  } else if (input.obesityCategory === "class1_obesity") {
    if (input.priorTreatmentAttempts === 0) {
      treatmentIntensity = "STAGE 2 — Structured Weight Management: Structured diet plan + increased physical activity + reduced sedentary time. Monthly provider visits. Refer to registered dietitian.";
      lifestyleIntervention = "Structured diet: balanced macronutrients, portion control, elimination of sugar-sweetened beverages. 60 min/day MVPA. Screen time <2 hours/day. Monthly visits with provider + RD.";
    } else {
      treatmentIntensity = "STAGE 3 — Comprehensive Multidisciplinary Intervention (CMDI): Refer to pediatric weight management program with multidisciplinary team (physician, RD, behavioral health, exercise specialist). Weekly visits for 12 weeks.";
      lifestyleIntervention = "Intensive multidisciplinary program: behavioral modification, structured meal plan (1200–1500 kcal/day for children, 1500–1800 kcal/day for adolescents), 60 min/day MVPA, family therapy.";
    }
    pharmacotherapy = input.ageYears >= 12
      ? "PHARMACOTHERAPY INDICATED (Class 1 obesity with comorbidities or failed lifestyle): Semaglutide (Wegovy) 0.25mg SC weekly → titrate to 2.4mg weekly over 16–20 weeks. FDA-approved ≥12 years. STEP TEENS trial: −16.1% BMI at 68 weeks."
      : input.ageYears >= 6
      ? "Orlistat (Xenical) 120mg TID with meals — FDA-approved ≥12 years. Off-label ≥6 years. Metformin for insulin resistance/prediabetes ≥10 years."
      : "Pharmacotherapy not approved <6 years. Lifestyle intervention only.";
    bariatricConsideration = "Not indicated for Class 1 obesity without severe comorbidities.";
  } else {
    // Class 2 or 3 obesity
    treatmentIntensity = `STAGE 3–4 — Comprehensive Multidisciplinary Intervention + Consider Pharmacotherapy/Surgery: Class ${input.obesityCategory === "class2_obesity" ? "2" : "3"} obesity. Intensive intervention required. Refer to pediatric weight management program.`;
    lifestyleIntervention = "Intensive multidisciplinary program (CMDI). Very low calorie diet (VLCD) may be considered under medical supervision. Family-based behavioral therapy. 60 min/day MVPA.";

    if (input.ageYears >= 12 && !input.hasContraindicationToGLP1) {
      pharmacotherapy = "PHARMACOTHERAPY STRONGLY INDICATED: Semaglutide (Wegovy) 0.25mg SC weekly → titrate to 2.4mg weekly. FDA-approved ≥12 years (BMI ≥95th %ile + weight-related comorbidity). STEP TEENS: −16.1% BMI. Monitor for nausea, pancreatitis, gallbladder disease. Contraindicated in MEN2, personal/family history of MTC.";
      recommendedAgents.push("Semaglutide (Wegovy) 0.25mg SC weekly → 2.4mg/week (≥12 years, BMI ≥95th %ile)");
      if (input.priorGLP1Use) {
        pharmacotherapy += " Prior GLP-1 use: consider tirzepatide (Zepbound) — FDA-approved ≥12 years (2024). 5mg SC weekly → titrate to 15mg weekly. SURMOUNT-TEEN: −15.4% BMI.";
        recommendedAgents.push("Tirzepatide (Zepbound) 5mg SC weekly → 15mg/week (≥12 years, 2024 FDA approval)");
      }
    } else if (input.ageYears >= 12 && input.hasContraindicationToGLP1) {
      pharmacotherapy = "GLP-1 RA CONTRAINDICATED: Consider orlistat 120mg TID (FDA-approved ≥12 years) or topiramate (off-label) for weight management. Metformin for insulin resistance.";
      recommendedAgents.push("Orlistat 120mg TID with meals (≥12 years)");
    } else {
      pharmacotherapy = "Pharmacotherapy limited for age <12 years. Metformin for insulin resistance/prediabetes ≥10 years. Refer to pediatric endocrinology.";
    }

    // Bariatric surgery
    if (input.ageYears >= 13 && (input.bmiPercentOfP95 >= 140 || (input.bmiPercentOfP95 >= 120 && (input.hasType2Diabetes || input.hasOSA || input.hasNASH || input.hasHypertension)))) {
      bariatricConsideration = "BARIATRIC SURGERY CANDIDATE (ASMBS 2023 criteria): BMI ≥140% of 95th %ile OR BMI ≥120% of 95th %ile + severe comorbidity (T2DM, OSA, NASH, HTN). Refer to pediatric bariatric surgery center. Sleeve gastrectomy preferred in adolescents. Roux-en-Y gastric bypass for T2DM. Requires multidisciplinary evaluation (surgery, psychology, nutrition, endocrinology).";
      if (!input.hasBariatricContraindication) {
        urgentFlags.push("BARIATRIC SURGERY CANDIDATE: Refer to pediatric bariatric surgery center per ASMBS 2023 criteria.");
      }
    } else {
      bariatricConsideration = input.ageYears >= 13
        ? "Bariatric surgery: criteria not yet met. Continue pharmacotherapy + CMDI. Reassess if BMI ≥140% of 95th %ile or severe comorbidities develop."
        : "Bariatric surgery: minimum age 13 years (ASMBS 2023). Continue pharmacotherapy + CMDI.";
    }
  }

  // ─── Comorbidity management ───────────────────────────────────────────────
  if (input.hasHypertension) {
    comorbidityMgmt.push("Hypertension: Weight loss is primary treatment. If BP persistently ≥95th %ile + 12 mmHg: initiate antihypertensive (ACE inhibitor or ARB). Refer to pediatric nephrology/cardiology.");
  }
  if (input.hasDyslipidemia) {
    comorbidityMgmt.push("Dyslipidemia: Dietary modification (reduce saturated fat, increase fiber). LDL ≥190 mg/dL: statin therapy (≥10 years). Refer to pediatric cardiology for severe dyslipidemia.");
    recommendedAgents.push("Atorvastatin 10–20mg/day (LDL ≥190 mg/dL, ≥10 years)");
  }
  if (input.hasNASH) {
    comorbidityMgmt.push("MASH/NASH: Weight loss 7–10% reduces hepatic steatosis. Avoid hepatotoxic medications. Monitor ALT/AST every 3–6 months. Refer to pediatric gastroenterology for biopsy-proven NASH.");
  }
  if (input.hasPCOS) {
    comorbidityMgmt.push("PCOS: Metformin 500–2000mg/day for insulin resistance and menstrual regulation. Weight loss improves ovulatory function. Refer to pediatric endocrinology/gynecology.");
    recommendedAgents.push("Metformin 500–2000mg/day (PCOS + insulin resistance)");
  }
  if (input.hasDepression || input.hasBingeEatingDisorder) {
    comorbidityMgmt.push("Mental health comorbidity: Refer to behavioral health for depression and/or binge eating disorder. Avoid weight-promoting antidepressants (e.g., mirtazapine, paroxetine). Consider CBT for binge eating.");
    urgentFlags.push("MENTAL HEALTH COMORBIDITY: Refer to behavioral health. Screen for depression (PHQ-9) and binge eating disorder.");
  }

  // ─── Family counseling ────────────────────────────────────────────────────
  counselingPoints.push(
    "Obesity is a chronic disease — not a personal failure. Use non-stigmatizing, patient-first language ('child with obesity' not 'obese child').",
    "Family-based treatment is more effective than child-only interventions — engage all household members.",
    "5-2-1-0 framework: 5+ fruits/vegetables/day, ≤2 hours recreational screen time, 1+ hour MVPA, 0 sugar-sweetened beverages.",
    "Meal planning: structured meals, no skipping breakfast, family meals ≥5 times/week associated with healthier weight.",
    "Sleep: inadequate sleep (< 9 hours in children, < 8 hours in adolescents) is an independent risk factor for obesity.",
    "Weight stigma: protect child from weight-based bullying. Address with school if needed."
  );

  if (input.familyMotivation === "low") {
    counselingPoints.push("Low family motivation: Use motivational interviewing techniques. Identify family-specific barriers. Consider referral to family therapy or social work.");
  }

  // ─── Monitoring ───────────────────────────────────────────────────────────
  const monitoringPlan = `Monthly weight/BMI monitoring during active treatment. Fasting glucose/HbA1c annually (or every 3 months if T2DM). Fasting lipid panel annually. ALT/AST annually (NASH risk). Blood pressure every visit. ${input.hasType2Diabetes ? "HbA1c every 3 months." : ""} ${recommendedAgents.some(a => a.includes("Semaglutide")) ? "Semaglutide: monitor for nausea, vomiting, pancreatitis (amylase/lipase if symptoms). Gallbladder ultrasound if RUQ pain." : ""}`;

  const primaryRec = urgentFlags.length > 0
    ? urgentFlags[0]
    : `PEDIATRIC OBESITY — ${input.obesityCategory.replace(/_/g, " ").toUpperCase()} (BMI ${input.bmiPercentile}th %ile, ${input.bmiPercentOfP95}% of 95th %ile). ${treatmentIntensity.split(":")[0]}. Evidence Level A (AAP CPG 2023).`;

  return {
    primaryRecommendation: primaryRec,
    treatmentIntensity,
    lifestyleIntervention,
    pharmacotherapy,
    bariatricConsideration,
    comorbidityManagement: comorbidityMgmt,
    urgentFlags,
    recommendedAgents,
    monitoringPlan,
    familyCounselingPoints: counselingPoints,
    evidenceLevel: "A",
    rationale: `Age ${input.ageYears} years. BMI ${input.bmiPercentile}th %ile (${input.bmiPercentOfP95}% of 95th %ile). Category: ${input.obesityCategory}. Prior treatment attempts: ${input.priorTreatmentAttempts}. Comorbidities: T2DM=${input.hasType2Diabetes}, HTN=${input.hasHypertension}, OSA=${input.hasOSA}, NASH=${input.hasNASH}. Recommendations per AAP CPG 2023 and ASMBS 2023.`,
    references: [
      { citation: "Hampl SE et al. Clinical Practice Guideline for the Evaluation and Treatment of Children and Adolescents with Obesity. Pediatrics. 2023;151(2):e2022060640.", url: "https://publications.aap.org/pediatrics/article/151/2/e2022060640" },
      { citation: "Weghuber D et al. Once-Weekly Semaglutide in Adolescents with Obesity. NEJM. 2022;387(24):2245–2257. (STEP TEENS)", url: "https://www.nejm.org/doi/10.1056/NEJMoa2208601" },
      { citation: "Pratt JSA et al. ASMBS Pediatric Metabolic and Bariatric Surgery Guidelines 2018 (updated 2023). Surg Obes Relat Dis. 2018;14(7):882–901.", url: "https://www.soard.org/article/S1550-7289(18)30174-5/fulltext" },
      { citation: "Jastreboff AM et al. Tirzepatide Once Weekly for the Treatment of Obesity in Adolescents. NEJM. 2024. (SURMOUNT-TEEN)", url: "https://www.nejm.org/doi/10.1056/NEJMoa2407701" },
    ],
  };
}
